<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,nextTick} from 'vue'
import {ElMessage} from 'element-plus'
import {api,post,state,connect,disconnect,stamp,uuid} from '../api'
import SopPlayer from '../components/SopPlayer.vue'
const sopUsed=ref<string|null>(null)
const messages=ref<any[]>([])
async function ack(id:string){await post('/api/messages/'+id+'/ack');messages.value=await api('/api/messages')}
const options=ref<any>({stations:[],orders:[],batches:[],processes:[]}),stationId=ref(''),batchId=ref(''),orderId=ref(''),chooser=ref(true),summary=ref<any>(),scan=ref(''),waiting=ref('主码'),busy=ref(false),notice=ref('等待扫描'),failed=ref(false),current=ref<any>(),scanEl=ref<any>(),tests=ref<any[]>([])
const station=computed(()=>options.value.stations.find((s:any)=>s.id===stationId.value)),process=computed(()=>options.value.processes.find((p:any)=>p.id===station.value?.processStepId)),orders=computed(()=>options.value.orders.filter((o:any)=>o.lineId===station.value?.lineId)),batches=computed(()=>options.value.batches.filter((b:any)=>b.workOrderId===orderId.value))
let pending:any=null,timer:ReturnType<typeof setInterval>,heartbeat:ReturnType<typeof setInterval>
async function refresh(){if(!stationId.value||!batchId.value)return;try{summary.value=await api(`/api/station/summary?stationId=${stationId.value}&batchId=${batchId.value}`);if(process.value?.sequence===3)tests.value=await api(`/api/tests?stationId=${stationId.value}&batchId=${batchId.value}`);messages.value=await api('/api/messages');state.lastUpdate=new Date().toISOString()}catch(e:any){notice.value=e.message;failed.value=true}}
async function choose(){if(!stationId.value||!batchId.value)return;try{await post('/api/station/reset',{requestId:uuid(),stationId:stationId.value,batchId:batchId.value,code:''});waiting.value=process.value.sequence===5?'SN':'主码';current.value=null;pending=null;scan.value='';chooser.value=false;failed.value=false;notice.value='等待扫描'+waiting.value;await refresh();await nextTick();scanEl.value?.focus()}catch(e:any){ElMessage.error(e.message)}}
async function submit(){if(busy.value||!scan.value||!state.online)return;busy.value=true;const code=scan.value;scan.value='';if(!pending||pending.code!==code)pending={requestId:uuid(),stationId:stationId.value,batchId:batchId.value,code,sopVersionId:sopUsed.value};try{const r=await post('/api/station/scan',pending);pending=null;waiting.value=r.waiting;notice.value=r.message;failed.value=false;current.value=r.trace;await refresh()}catch(e:any){notice.value=e.message;failed.value=true;if(state.online)pending=null}finally{busy.value=false;await nextTick();scanEl.value?.focus()}}
async function reset(){await choose()}
onMounted(async()=>{try{options.value=await api('/api/station/options');await connect(refresh);timer=setInterval(async()=>{try{await api('/api/health');if(!state.connected)await connect(refresh);await refresh()}catch{}},15000);heartbeat=setInterval(()=>{if(stationId.value&&batchId.value&&state.online)post('/api/station/heartbeat',{requestId:uuid(),stationId:stationId.value,batchId:batchId.value,code:''}).catch(()=>{})},30000)}catch(e:any){ElMessage.error(e.message)}})
onUnmounted(()=>{clearInterval(timer);clearInterval(heartbeat);disconnect()})
</script>
<template><div class="stationbar"><div><b>工位终端 · {{station?.code||'请选择授权工位'}}</b><p class="sub">{{process?.name}} · {{state.user?.name}}</p></div><div class="actions"><span :class="{'offline':!state.online}">{{state.online?'在线':'断网 · 禁止过站'}}</span><el-button @click="chooser=true">⇄ 切换工位</el-button></div></div><main class="content"><el-alert v-if="!state.online" title="网络已断开，禁止离线过站；可继续查看已缓存 SOP。连接恢复后重新扫描同一码。" type="error" :closable="false"/><section v-if="summary" class="panel station-order"><div class="panelhead"><h2>{{summary.order.code}} · 批次 {{summary.batch.code}}</h2><span>{{station?.name}}</span></div><div class="stats"><div class="stat"><span>工单计划</span><strong>{{summary.order.plan}}</strong></div><div class="stat"><span>批次计划</span><strong>{{summary.batch.plan}}</strong></div><div class="stat"><span>本工位完成</span><strong>{{summary.done}}</strong></div><div class="stat"><span>批次剩余</span><strong>{{summary.remaining}}</strong></div></div></section><div v-if="station&&!chooser" class="stationlayout"><section class="panel"><h2>SOP · {{process?.name}}</h2><SopPlayer :process-id="station.processStepId" @loaded="id=>sopUsed=id"/></section><section v-if="process?.sequence!==3" class="panel"><div class="panelhead"><h2>扫码作业</h2><span class="badge teal">等待{{waiting}}</span></div><p class="sub">使用同一把扫码枪连续扫描，Enter / Tab 自动提交</p><el-input ref="scanEl" v-model="scan" class="auto-scan" :placeholder="'请扫描'+waiting" :disabled="busy||!state.online" autofocus autocomplete="off" @keydown.enter.prevent="submit" @keydown.tab.prevent="submit"/><div class="statusbox" :class="{fail:failed}" role="status"><h2>{{notice}}</h2></div><el-button @click="reset">重新扫描{{process?.sequence===5?'SN':'主码'}}</el-button><div v-if="current"><div v-for="(label,key) in {mainCode:'主码',cellCode:'电芯码',snCode:'SN',packCode:'包装码'}" :key="key" class="summaryrow"><span>{{label}}</span><b>{{current.unit[key]||'未绑定'}}</b></div><div class="timeline"><div v-for="p in current.passages" :key="p.id" class="event"><b>{{options.processes.find((x:any)=>x.id===p.processStepId)?.name}}</b><p>{{stamp(p.at)}}</p></div></div></div></section><section v-else class="panel"><h2>仪器自动测试结果</h2><p class="sub">由仪器扫描主码并启动测试，MES 自动接收结果。</p><div v-if="tests[0]" class="instrument-result" :class="{isfail:tests[0].result.verdict==='FAIL'}"><h1>{{tests[0].result.verdict}}</h1><div>{{tests[0].mainCode}}<p>{{stamp(tests[0].result.receivedAt)}}</p></div></div><p v-else>等待仪器上传结果</p><div class="test-history"><el-table :data="tests"><el-table-column prop="mainCode" label="主码"/><el-table-column prop="result.verdict" label="结果"/><el-table-column label="接收时间"><template #default="{row}">{{stamp(row.result.receivedAt)}}</template></el-table-column></el-table></div></section></div><section v-if="messages.length" class="panel"><h2>工位消息</h2><div v-for="m in messages" :key="m.message.id" class="lineitem"><div class="fill"><b>{{m.message.important?'【重要】':''}}{{m.message.title}}</b><p>{{m.message.body}}</p></div><el-button :disabled="m.acked||!state.online" @click="ack(m.message.id)">{{m.acked?'已确认':'确认收到'}}</el-button></div></section><section v-if="summary" class="panel"><h2>最近过站记录</h2><el-table :data="summary.recent"><el-table-column prop="u.mainCode" label="主码"/><el-table-column prop="u.cellCode" label="电芯码"/><el-table-column prop="u.snCode" label="SN"/><el-table-column prop="u.packCode" label="包装码"/><el-table-column label="时间"><template #default="{row}">{{stamp(row.pass.at)}}</template></el-table-column></el-table></section></main><el-dialog v-model="chooser" title="切换授权工位与工单" :close-on-click-modal="false" :show-close="!!summary"><el-form label-width="80"><el-form-item label="工位"><el-select v-model="stationId" @change="orderId='';batchId=''" placeholder="选择授权工位"><el-option v-for="s in options.stations" :key="s.id" :value="s.id" :label="s.code+' · '+s.name"/></el-select></el-form-item><el-form-item label="工单"><el-select v-model="orderId" @change="batchId=''"><el-option v-for="o in orders" :key="o.id" :value="o.id" :label="o.code"/></el-select></el-form-item><el-form-item label="批次"><el-select v-model="batchId"><el-option v-for="b in batches" :key="b.id" :value="b.id" :label="b.code"/></el-select></el-form-item></el-form><p v-if="!options.stations.length" class="sub">当前用户没有授权工位，请管理员配置。</p><template #footer><el-button type="primary" :disabled="!batchId" @click="choose">进入工位</el-button></template></el-dialog></template>
